def test_the_script_carries_no_retired_word(self):
        text = read(HOOK_SCRIPT).lower()
        # Spelled in halves so this file does not carry the words either.
        for word in ('rece' + 'ipt', 'au' + 'dit', 'ga' + 'uge',
                     'str' + 'ict', 'fo' + 'rge'):
            assert word not in text
